def midpoint_date(date1, date2):
    def leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    md = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    def to_days(y, m, d):
        days = d + sum(md[i] + (1 if i == 1 and leap(y) else 0) for i in range(m - 1))
        yb = y - 1
        return days + yb * 365 + yb // 4 - yb // 100 + yb // 400
    def to_date(total):
        y = total * 400 // 146097 + 1
        while to_days(y, 1, 1) > total:
            y -= 1
        while to_days(y + 1, 1, 1) <= total:
            y += 1
        rem = total - to_days(y, 1, 1)
        m = 1
        while rem >= md[m - 1] + (1 if m == 2 and leap(y) else 0):
            rem -= md[m - 1] + (1 if m == 2 and leap(y) else 0)
            m += 1
        return (y, m, rem + 1)
    d1 = to_days(*date1)
    d2 = to_days(*date2)
    return to_date(d1 + (d2 - d1) // 2)

