def zigzag_check(lst):
    n = len(lst)
    if n < 2:
        return True
    pairs = list(zip(lst, lst[1:]))
    if any(a == b for a, b in pairs):
        return False
    signs = [1 if b > a else -1 for a, b in pairs]
    return all(signs[i] != signs[i + 1] for i in range(len(signs) - 1))

def weekend_count_given_start_weekday(start_weekday, num_days):
    full_weeks, remainder = divmod(num_days, 7)
    count = full_weeks * 2
    for i in range(remainder):
        if (start_weekday + i) % 7 in (5, 6):
            count += 1
    return count

