import re

def is_valid_domain_name(s):
    labels = s.split('.')
    if len(labels) < 2:
        return False
    label_pattern = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?$')
    if not all(label_pattern.match(label) for label in labels):
        return False
    return bool(re.fullmatch(r'[A-Za-z]{2,}', labels[-1]))

